<body>
<h1>ブロック崩し</h1>
<div id="hud">
  <span>SCORE <b id="score">0</b></span>
  <span>LEVEL <b id="level">1</b></span>
  <span>LIVES <b id="lives">3</b></span>
  <span>BEST <b id="best">0</b></span>
</div>
<div id="wrap">
  <canvas id="game" width="640" height="480"></canvas>
  <div id="overlay">
    <div class="big" id="ovTitle">ブロック崩し</div>
    <div class="sub" id="ovText">マウスまたは ← → キーでパドルを操作<br>スペースキーでボール発射</div>
    <button id="ovBtn">スタート</button>
  </div>
</div>
<div id="help">マウス / ←→キー: 移動 ・ スペース: 発射 ・ P: 一時停止</div>

<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  const scoreEl = document.getElementById('score');
  const levelEl = document.getElementById('level');
  const livesEl = document.getElementById('lives');
  const bestEl  = document.getElementById('best');
  const overlay = document.getElementById('overlay');
  const ovTitle = document.getElementById('ovTitle');
  const ovText  = document.getElementById('ovText');
  const ovBtn   = document.getElementById('ovBtn');

  // ---------- 状態 ----------
  let state = 'menu'; // menu | ready | playing | paused | gameover | clear
  let score = 0, level = 1, lives = 3;
  let best = 0;
  try { best = +localStorage.getItem('breakout_best') || 0; } catch (e) {}
  bestEl.textContent = best;

  const paddle = { w: 96, h: 14, x: W / 2 - 48, y: H - 34, speed: 520 };
  const ball = { x: 0, y: 0, r: 7, vx: 0, vy: 0, speed: 320, stuck: true };

  let bricks = [];
  const BRICK_ROWS_BASE = 5, COLS = 10;
  const BRICK_W = 56, BRICK_H = 20, BRICK_GAP = 6;
  const BRICK_TOP = 60, BRICK_LEFT = (W - (COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;

  const ROW_COLORS = ['#ff5f6d', '#ff9f43', '#feca57', '#1dd1a1', '#54a0ff', '#a55eea', '#fd79a8'];

  const keys = {};
  let mouseX = null;

  // ---------- サウンド ----------
  let audioCtx = null;
  function beep(freq, dur = 0.06, type = 'square', vol = 0.15) {
    try {
      audioCtx ||= new (window.AudioContext || window.webkitAudioContext)();
      const o = audioCtx.createOscillator();
      const g = audioCtx.createGain();
      o.type = type; o.frequency.value = freq;
      g.gain.setValueAtTime(vol, audioCtx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
      o.connect(g); g.connect(audioCtx.destination);
      o.start(); o.stop(audioCtx.currentTime + dur);
    } catch (e) {}
  }

  // ---------- レベル生成 ----------
  function buildLevel() {
    const rows = Math.min(BRICK_ROWS_BASE + (level - 1), ROW_COLORS.length);
    bricks = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < COLS; c++) {
        // 上位レベルでは一部ブロックを強化(2回叩く)
        const hp = (level >= 3 && r < 2) ? 2 : 1;
        bricks.push({
          x: BRICK_LEFT + c * (BRICK_W + BRICK_GAP),
          y: BRICK_TOP + r * (BRICK_H + BRICK_GAP),
          w: BRICK_W, h: BRICK_H,
          color: ROW_COLORS[r % ROW_COLORS.length],
          hp,
          points: (rows - r) * 10
        });
      }
    }
  }

  function resetBall() {
    ball.stuck = true;
    ball.speed = 300 + (level - 1) * 30;
    ball.vx = 0; ball.vy = 0;
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r - 1;
    state = 'ready';
   "}
